#include <stdint.h>
typedef struct {
    volatile uint32_t CTRL;   /* offset 0x00 */
    volatile uint16_t CNT;    /* offset 0x04 */
    uint16_t          RSV0;   /* offset 0x06, padding */
    volatile uint32_t LOAD;   /* offset 0x08 */
    volatile uint8_t  FLAG;   /* offset 0x0C, sizeof = 16 */
} TMR_Type;
#define TMR0 ((TMR_Type *)0x40000400u)
/* TMR0->LOAD = 999u; writes the word at 0x40000408 */

questions.questionText:
Assume C11 on a little-endian processor such as x86 or a typical ARM Cortex-M. What does this program print?

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t x = 0x12345678u;
    uint8_t *p = (uint8_t *)&x;
    printf("%02X %02X\n", p[0], p[3]);
    return 0;
}

Assume C11 with uint16_t aligned on 2 bytes and uint32_t on 4 bytes. A UART's registers are accessed through the structure overlay below. At which address does the statement UART1->BRR = 0x0683; write?

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t SR;
    volatile uint16_t DR;
    uint16_t          RSV;
    volatile uint32_t BRR;
} UART_Type;
#define UART1 ((UART_Type *)0x40011000u)
